-- 外部相应按钮点击, 执行一次 idle 100 <-> 200 切换:
function IdolLive3D_InteractiveManagerV2:_CallIdleSwitchByButton( key_ ) -- v2
    if self._workType == WorkType.Interactive then
        print("当前不在 idle stage -1-")
        return
    end
    ---
    local currentIdleStage = self:FindCurrentPlayingIdleState()
    if isNull(currentIdleStage) then 
        print("当前不在 idle stage -2-")
        return
    end 
    ---
    local freeCameraSpatialParams = self:_GetFreeCameraSpatialParams()
    if isNull(freeCameraSpatialParams) then 
        return
    end
    ---
    local tgtStageJump = nil
    for _,stageJump in pairs(self.roleAnimatorMgr.frontStageJson.stageJumps) do
        if  stageJump.interactiveType == IdolLive3D_States.InteractiveType.Touch and
            string.lower(stageJump.touchKey) == string.lower(key_) and
            IdolLive3D_Utils:IsCameraSpatialParamsInRange(stageJump.cameraSpatialRange, freeCameraSpatialParams, stageJump.compareMode ) 
        then
            tgtStageJump = stageJump
            break
        end
    end
    if tgtStageJump == nil then 
        printError("json 文件中没找到 touchKey 为 " .. tostring(key_) .. " 的 stageJump")
        return
    end 
    --- 
    local tgtStageJson = tgtStageJump.tgtStageJson
    local isIdleStateChange = self.cachedIdleState ~= tgtStageJson.idleState
    if isIdleStateChange ~= true then 
        printError("自己 跳入 自己 ? 请检查;  暂时放弃 jump")
        return
    end 
    ---
    self.idleSwitchData.cachedTargetStageJson = tgtStageJson
    self.idleSwitchData.stageJumpType = IdolLive3D_States.StageJumpType.FromUIButton
    --self:_StageSwitchCheckByJump()
end



-- 外部调用者不关心 当前是否在 target idle; 可用本函数实现 idle 100->100 的强制切换; 
-- 通常使用本函数来强播一遍 全屏转场特效
function IdolLive3D_InteractiveManagerV2:ForceToTargetStage( stageJson_, stageJumpType_ )
    local currentPlaying_IdleState = self:FindCurrentPlayingIdleState()
    if isNull(currentPlaying_IdleState) then 
        print( "想用 按钮 切换 idle, 但当前不在 idle state" )
        return
    end
    assert( isNotNull(stageJson_) )
    assert( isNotNull(stageJumpType_) )
    self.idleSwitchData.cachedTargetStageJson = stageJson_
    self.idleSwitchData.stageJumpType = stageJumpType_
end





-- ============================= timeline States ==================================


function IdolLive3D_InteractiveManagerV2:_InitSuperTimelineStates( superTimelineTFMaps_, runtimeRootTF_ )
    if table.count(superTimelineTFMaps_) == 0 then 
        return
    end 

    self.superTimelineStateEnvMaps = {}
    for superTimelineName,tfsMap in pairs(superTimelineTFMaps_) do 
        local superTimelineJson = self.baseJson:Find_SuperTimelineState(superTimelineName)
        assert( isNotNull(superTimelineJson) )
        ---
        local superTLGo = GameObject("super." .. superTimelineName)
        superTLGo.transform:SetParent(runtimeRootTF_)
        local superEnv = AddLuaBehaviour(superTLGo, "Game.IdolLive3D.V2.IdolLive3D_SuperTimeLineStateV2").Env
        superEnv:Init( self, self.roleAnimator, tfsMap, superTimelineJson )

        self.superTimelineStateEnvMaps[superTimelineName] = superEnv
        CfUtils.SetActive( superTLGo, true )
    end 
end


