function IdolLive3D_InteractiveManagerV2:FindCurrentPlayingIdleState()
    return self.roleAnimatorMgr:FindCurrentPlayingIdleState()
end
 

-- 协程:
function IdolLive3D_InteractiveManagerV2:WaitUntilIdleState()
    local isWaited = false
    for i=0, 2000 do 
        if isNotNull(self:FindCurrentPlayingIdleState()) then
            isWaited = true
            break
        end 
        printError("-wait-")
        coroutine.yield(Yielders.EndOfFrame)
    end 
    if isWaited == false then 
        printError("始终没等到 FindCurrentPlayingIdleState 结束")
    end
end



