function IdolLive3D_InteractiveManagerV2:SelfUpdate()
    if self.isInit ~= true or self.idolLive3D_Main.isInit ~= true then
        return
    end

    -- debug:
    if IdolLive3D_Utils.IsEditorPlatform() then

        -- 编辑模式下 idle 切换热键:
        if Input.GetKeyDown(KeyCode.Alpha1) then 
            
        elseif Input.GetKeyDown(KeyCode.Alpha2) then 
            
        elseif Input.GetKeyDown(KeyCode.Alpha3) then
            printError("暂未实现")
        elseif Input.GetKeyDown(KeyCode.Alpha4) then 
            printError("暂未实现")
        end
        -- 开关 debug UI:
        if Input.GetKeyDown(KeyCode.Alpha0) then 
            Events.Broadcast(IdolLive3D_States.EventShowDebugUI, true) -- 参数无所谓了
        end
    end


    -- ======================================= 正文 ===========================================

    --- 起步阶段
    if self.longFrameCount == 0 then 
        -- !! 为了让 第一帧的 _IntoFirstStage() 能执行成功, 未来要改用更好的办法
        --printError("跳过 0 帧")
        self.longFrameCount = self.longFrameCount + 1
        return

    elseif self.longFrameCount == 1 then 

        local isFstIntoSuperTimeline = isNotNull(self.baseJson.firstTimelineState)

        -- 先进入第一个 stage idle:
        self:_IntoFirstStage( isFstIntoSuperTimeline == false )

        -- 再进入第一个 superTL:
        if isFstIntoSuperTimeline then 
            -- 入场自动播放 timeline:
            self:IntoInitSuperTimelineIState( self.baseJson.firstTimelineState ) -- !! todo 改到这里
        end

    elseif self.longFrameCount == 2 then

        -- !!! 临时放这儿, 没有解决 lookat 头部闪跳的问题
        self.idolLive3D_Main.roleLookAtController.target = self.mainCamera.transform
        -- self.idolLive3D_Main.roleLookAtController.weight = 0

    end 
    if self.longFrameCount < 999999 then 
        self.longFrameCount = self.longFrameCount + 1
    end


    --- 播放 动作内音效
    self:UpdateSoundsInsideInteractive()


    local freeCameraSpatialParams = self:_GetFreeCameraSpatialParams()
    if isNull(freeCameraSpatialParams) then 
        return
    end

    --- camera lookat system:
    -- 因为 lookat 的开关涉及 自由相机机位, 所以必须轮询;
    local currentIsLookCamera = IdolLive3D_Utils:IsCameraSpatialParamsInRange( self:Get_LookCameraSpatialRange(), freeCameraSpatialParams, nil ) 
                                    and self:CurrentInteractiveStateIsOpenLookAt()

    local isLookCameraChangeThisFrame = (currentIsLookCamera ~= self.lastIsLookCamera)
    if isLookCameraChangeThisFrame then 
        self.lastIsLookCamera = currentIsLookCamera
        if currentIsLookCamera == true then 
            print(" 进入 look camera 区 ")
            --self.idolLive3D_Main.roleLookAtController.target = self.mainCamera.transform
            self.idolLive3D_Main.roleLookAtController.weight = 1
        else 
            print(" 离开 look camera 区 ")
            --self.idolLive3D_Main.roleLookAtController.target = nil
            self.idolLive3D_Main.roleLookAtController.weight = 0
        end 
    end 


    local cameraMode = self.idolLive3D_CameraEnv:GetCameraMode()
    local isInteractiveFreeze = cameraMode == IdolLive3D_States.CameraMode.Freeze and IdolLive3D_States.isSupportInteractiveInFreeze == true
    if not (cameraMode == IdolLive3D_States.CameraMode.FreeManual or isInteractiveFreeze) then 
        return
    end 

    -- 机位触发的 stage 切换: 
    -- (会打断 freeSound )
    self:_StageSwitchCheckBySpacial( freeCameraSpatialParams )

    -- superTimeline / ui btn 触发的 stage 切换:
    self:_StageSwitchCheckByJump()

    -- 触发 机位型 交互:
    -- (会打断 freeSound )
    if self._workType ~= WorkType.Interactive then
        local currentSpacialState = self:FindSpacialState( freeCameraSpatialParams ) -- 可能为 nil
        local isSpacialStateChangeThisFrame = (self.spacialState ~= currentSpacialState)
        self.spacialState = currentSpacialState

        if isNotNull(currentSpacialState) and isSpacialStateChangeThisFrame then 
            print("spacial state 发生变化 -> " .. tostring(currentSpacialState.name) )
            self:IntoInteractiveState( currentSpacialState )
        end 
    end 

    -- 触发 自由音效 (机位触发的):
    -- 当发现 simple/tl动作 的语音没有播完时, 自由音效 无法被触发;
    if self._workType == WorkType.None and IdolLive3D_Sounds:IsAnyVoicePlaying() == false then

        local currentFreeSoundState = self:FindFreeSoundState( freeCameraSpatialParams ) -- 可能为 nil
        local isFreeSoundStateChangeThisFrame = (self.freeSoundState ~= currentFreeSoundState)
        self.freeSoundState = currentFreeSoundState

        if isNotNull(currentFreeSoundState) and isFreeSoundStateChangeThisFrame then 
            print("free sound state 发生变化 -> " .. tostring(currentFreeSoundState.annotation) )
            self:IntoFreeSoundState( currentFreeSoundState )
        end 
    end

    
    if self.frameCount < 99999 then
      self.frameCount = self.frameCount + 1
    end


    ---- 
    -- 当发现 animator 已经进入 idle state 后, 会将 _workType 复位
    -- 每帧都主动计算:
    self.currentPlayingIdleState = self.roleAnimatorMgr:FindCurrentPlayingIdleState()
    if isNotNull(self.currentPlayingIdleState) then 
        if self._workType == WorkType.Interactive then 
            self._workType = WorkType.None -- 允许触发下一个 互动
            self:_CheckAndHideSimpleFX() -- !! Must Before AddToQueue()
            self:AddToQueue( self.currentPlayingIdleState )
        end 
    end 
end


-- 点击 模型身上的碰撞体, 触发的实体 touch交互:
function IdolLive3D_InteractiveManagerV2:_OnSimpleTap( gesture_ )
    if self.isInit ~= true then
        return
    end
    print( "tap" )
    ---
    local tapPos2 = gesture_.startPosition
    local tapPos3 = Vector3( tapPos2.x, tapPos2.y, 0.0 )
    local ray = self.mainCamera:ScreenPointToRay(tapPos3) -- Ray
    ---
    local legalHitInfos = {} -- 所有携带了 ID组件的 trigger 碰撞体信息
    local raycastHits, raycastHitsNum = IdolLive3D_Utils.RaycastNonAlloc( ray.origin, ray.direction, 20.0, IdolLive3D_StatesV2.collideLayerMask, QueryTriggerInteraction.Collide )
    --printError("hit num = " .. tostring(raycastHitsNum))
    for i=0, raycastHitsNum-1 do 
        local hit = raycastHits[i]
        if isNotNull(hit) and isNotNull( hit.collider) then
            local idComp = KTool.GetComponent(hit.collider.gameObject, typeof(IDComp))
            if  isNotNull(idComp) and
                idComp.id == ColliderIdType.Base and -- 过滤掉其它的类型
                type(idComp.stringId) == "string" and (#idComp.stringId > 0) 
            then 
                table.insert( legalHitInfos, {distance = hit.distance, idStr = idComp.stringId} )
            end
        end
    end
    ---
    if #legalHitInfos == 0 then 
        Events.Broadcast(IdolLive3D_States.EventSimpleTapInAnyTime, IdolLive3D_StatesV2.emptySimpleTapName) -- 表示啥也没点到
        return
    end 
    -- 距离由近及远
    table.sort(legalHitInfos, function(a, b) return checkNumber(a.distance) < checkNumber(b.distance) end)
    local nearestIDStr = string.lower(legalHitInfos[1].idStr)
    if string.isEmpty(nearestIDStr) then 
        Events.Broadcast(IdolLive3D_States.EventSimpleTapInAnyTime, IdolLive3D_StatesV2.emptySimpleTapName) -- 表示啥也没点到
        return
    end 
    --------------------- 
    print("tap: " ..tostring(nearestIDStr))
    Events.Broadcast(IdolLive3D_States.EventSimpleTapInAnyTime, nearestIDStr) 
    self:_HandleTouch(nearestIDStr)
end


-- 点击 ui按钮, 触发的虚拟 touch交互:
function IdolLive3D_InteractiveManagerV2:OnVirtualSimpleTap( touchKey_ )
    touchKey_ = tostring(touchKey_)
    Events.Broadcast(IdolLive3D_States.EventSimpleTapInAnyTime, touchKey_) 
    self:_HandleTouch(touchKey_)
end



function IdolLive3D_InteractiveManagerV2:_HandleTouch( touchKey_ )
    touchKey_ = tostring(touchKey_)
    --printError("touchKey_ = " .. tostring(touchKey_))
    --------------------
    local cameraMode = self.idolLive3D_CameraEnv:GetCameraMode()
    local isInteractiveFreeze = cameraMode == IdolLive3D_States.CameraMode.Freeze and IdolLive3D_States.isSupportInteractiveInFreeze == true
    if not (cameraMode == IdolLive3D_States.CameraMode.FreeManual or isInteractiveFreeze) then 
        return
    end 
    -- (允许中断 freeSound)
    if self._workType == WorkType.Interactive then
        return
    end 

    local newState = self:FindTouchState( self:_GetFreeCameraSpatialParams(), touchKey_ )
    if isNotNull(newState) then 
        -- 当角色在 idle 100 <-> 200 间过度时, 此时若触发交互, 动画将无法被播放, 但声音能播出来, 导致异常; 
        -- 此处直接阻止进入交互
        if self.roleAnimatorMgr:IsAnimatorStateInfoInIdle() == nil then
            print("点击, 但当前尚未进去 idle 状态, 触发失败")
            return
        end
        print("点击 - " .. tostring(newState.name) )
        self:IntoInteractiveState( newState )
    else 
        -- !! 这是允许的, 有时对应功能会写在 custom脚本内, 以此来支持更加复杂多变的需求...
        print("未找到点击对应的 iState")
    end
end



function IdolLive3D_InteractiveManagerV2:Update_LookAtIKParamsV2( idleState_ )
    IdolLive3D_Utils.CopyToLookAtIK( self.lookAtIK, idleState_.stage.roleParams.lookatParams.lookAtIKParams )
end



function IdolLive3D_InteractiveManagerV2:Get_LookCameraSpatialRange()
    return self.roleAnimatorMgr.frontStageJson.roleParams.LookCameraSpatialRange
end 


-- 检查当前 自由轨道相机机位 是否位于 iState_ 的触发区间:
---@return boolean
function IdolLive3D_InteractiveManagerV2:IsFreeTrackCameraInTargetIStateRange( iState_ ) 
    local freeCameraSpatialParams = self:_GetFreeCameraSpatialParams()
    local ret = IdolLive3D_Utils:IsCameraSpatialParamsInRange(iState_.cameraSpatialRange, freeCameraSpatialParams, iState_.compareMode )
    return ret
end


