    self:IntoStage_Jump( stageJson, isPlaySounds_ )
end



-- 仅检查 机位触发的 Stage switch
function IdolLive3D_InteractiveManagerV2:_StageSwitchCheckBySpacial( freeCameraSpatialParams_ )
    if self._workType == WorkType.Interactive then
        return
    end

    if isNotNull( self.idleSwitchData.cachedTargetStageJson ) then 
        return
    end

    local currentStageJson = self.roleAnimatorMgr.frontStageJson
    for _,stageJump in pairs(currentStageJson.stageJumps) do
        if stageJump.interactiveType == IdolLive3D_States.InteractiveType.Spacial and
            IdolLive3D_Utils:IsCameraSpatialParamsInRange(stageJump.cameraSpatialRange, freeCameraSpatialParams_, stageJump.compareMode ) 
        then 
            -- 找到目标 stage
            local tgtStageJson = stageJump.tgtStageJson
            ---
            self.cachedIdleState = tgtStageJson.idleState
            self:IntoStage_Smooth( tgtStageJson, true )
            break
        end
    end
end



-- superTimeline / uiButton 触发的 stage idle 切换:
function IdolLive3D_InteractiveManagerV2:_StageSwitchCheckByJump()
    if self._workType == WorkType.Interactive then
        return
    end

    if isNull( self.idleSwitchData.cachedTargetStageJson ) then 
        return
    end

    if IdolLive3D_States.IsStageJumpType(self.idleSwitchData.stageJumpType) == false then 
        printError("数据异常, stageJumpType = " .. tostring(self.idleSwitchData.stageJumpType))
        return
    end

    if UIRaycastBlocker:ContainsCondition(IdolLive3D_States.BlockerKeys.StageJump)  then 
        printError("正在 stage jump 中, 放弃本次 jump")
        return
    end 

    -- 缓存数据:
    local newStageJson = self.idleSwitchData.cachedTargetStageJson
    local newIdleState = self.idleSwitchData.cachedTargetStageJson.idleState
    local stageJumpType = self.idleSwitchData.stageJumpType
    self.idleSwitchData.cachedTargetStageJson = nil  -- !! MUST  
    self.idleSwitchData.stageJumpType = nil  -- !! MUST  

    --- 
    local isIdleStateChange = self.cachedIdleState ~= newIdleState
    self.cachedIdleState = newIdleState

    -- superTimeline 支持无条件转场:
    if isIdleStateChange == true or stageJumpType == IdolLive3D_States.StageJumpType.FromSuperTimeline then 
        --printError("切 idle")
        --- 正式切换:   

        UIRaycastBlocker:AddCondition(IdolLive3D_States.BlockerKeys.StageJump) ---
        xTry(function()
            CoStop(self.co_1)
            self.co_1 = CoStart(function()
                
                self:AddToQueue( stageJumpType == IdolLive3D_States.StageJumpType.FromSuperTimeline and 
                                    self.baseJson.stageJump_name_to_InteractiveStates.jump_superTimeline or 
                                    self.baseJson.stageJump_name_to_InteractiveStates.jump_UI
                )            

                if self.fullScreenFXEnv.state == IdolLive3D_States.FullScreenFXState.Hide then 
                    cs_coroutine.yield_return( self.fullScreenFXEnv:FadeIn() ) --- 全屏特效 淡入
                end 

                self:IntoStage_Jump( newStageJson, true )

                if self.fullScreenFXEnv.state == IdolLive3D_States.FullScreenFXState.Show then 
                    cs_coroutine.yield_return( self.fullScreenFXEnv:FadeOut() ) -- 全屏特效 淡出
                end

                UIRaycastBlocker:RemoveCondition(IdolLive3D_States.BlockerKeys.StageJump) ---
            end)
        end, function()
            printError("xTry end RemoveCondition: "..tostring(IdolLive3D_States.BlockerKeys.StageJump))
            UIRaycastBlocker:RemoveCondition(IdolLive3D_States.BlockerKeys.StageJump) ---
        end)

    end
end




-- 瞬跳, 不走 toIdle;
---@param isNotUseInitCameraSpatialParams_ boolean | nil
function IdolLive3D_InteractiveManagerV2:IntoStage_Jump( stageJson_, isPlaySounds_, isNotUseInitCameraSpatialParams_ )
    local idleState = stageJson_.idleState
    local lastStageJson = self.roleAnimatorMgr.frontStageJson

    self.idolLive3D_Main:OnSwitchStage( stageJson_ )
    self.idolLive3D_CameraEnv:OnSwitchStage( stageJson_, isNotUseInitCameraSpatialParams_ ) 
    self.roleAnimatorMgr:SwitchToNewStage( stageJson_, true )
    self:AddToQueue( idleState )
    self:Update_LookAtIKParamsV2( idleState )  -- 配置 LookAtIK 参数:

    --- 音效, 字幕:
    if isPlaySounds_ == true and self:IsPlayTimesOverflow(idleState) == false then 
        self:PlayVideoSubtitle(idleState.videoSubtitle) -- 播放字幕
        self:RegistSounds( idleState, false )
    end 
    idleState.playTimes = idleState.playTimes + 1

    --- sceneNodes: 
    IdolLive3D_BaseParamsJsonDataV2.HandleSceneNodes( lastStageJson.sceneNodesMgr, false )
    IdolLive3D_BaseParamsJsonDataV2.HandleSceneNodes( stageJson_.sceneNodesMgr, true )

    print( "正式切入: " .. tostring(idleState.name) )
    ---
end



-- 协程
-- 先进入 toIdle, 后进入 Idle
function IdolLive3D_InteractiveManagerV2:IntoStage_Smooth( stageJson_, isPlaySounds_ )
    local idleState = stageJson_.idleState    
    local lastStageJson = self.roleAnimatorMgr.frontStageJson

    local toIdleState = IdolLive3D_BaseParamsJsonDataV2.FindToIdleState( lastStageJson, stageJson_ ) 
    assert( isNotNull(toIdleState) )

    -- 本协程存在的目的主要为了将 "idle switch" 和 "new idle" 两个阶段拆分开; 分别 AddToQueue();
    CoStop(self.co_2)
    self.co_2 = CoStart(function()
        --1--
        self.idolLive3D_Main:OnSwitchStage( stageJson_ )
        self.idolLive3D_CameraEnv:OnSwitchStage( stageJson_, true ) 
        self.roleAnimatorMgr:SwitchToNewStage( stageJson_, false )
        self:AddToQueue( toIdleState )
        --2--
        -- 等待 idle 切换完毕; 只等待有限帧:
        local isSwitchSuccess = false
        for i=0, 5000 do  
            if self.roleAnimatorMgr:IsAnimatorStateInfoInIdle() then 
                isSwitchSuccess = true
                break
            end 
            --printError("--")
            coroutine.yield(Yielders.EndOfFrame)
        end
        if isSwitchSuccess == false then 
            printError("idle 切换 似乎未正式完成, 请检查")
        end 
        --3--
        self:AddToQueue( idleState )
        self:Update_LookAtIKParamsV2( idleState )  -- 配置 LookAtIK 参数:
        --- 音效, 字幕:
        if isPlaySounds_ == true and self:IsPlayTimesOverflow(idleState) == false then 
            self:PlayVideoSubtitle(idleState.videoSubtitle) -- 播放字幕
            self:RegistSounds( idleState, false )
        end 

        --- sceneNodes: 
        IdolLive3D_BaseParamsJsonDataV2.HandleSceneNodes( lastStageJson.sceneNodesMgr, false )
        IdolLive3D_BaseParamsJsonDataV2.HandleSceneNodes( stageJson_.sceneNodesMgr, true )

        idleState.playTimes = idleState.playTimes + 1
        print( "正式切入: " .. tostring(idleState.name) )
    end)
end


