-- 进入交互状态
---@return boolean @ 是否成功进入目标 state
function IdolLive3D_InteractiveManagerV2:IntoInteractiveState( iState_ )
    if type(iState_) ~= "table" then 
        printError("koko- 参数异常")
        return false
    end 

    -- 外部已经做过一层屏蔽了, 此处这个检测有点多余
    if self._workType == WorkType.Interactive then
        print("koko - 放弃进入状态: " .. tostring(iState_.name) .. "; isWorking = " .. tostring(self._workType)  )
        return false
    end     

    if iState_.stateType == StateType.Simple then 
        self.roleAnimatorMgr:PlaySimpleIState(iState_)

        -- sounds: 
        self:RegistSounds( iState_, true )

        -- 播放 fx: (如果有)
        if isNotNull(iState_.fxTF) then 
            KTool.SetActive( iState_.fxTF.gameObject, true )
        end 

        self:BroadcastPlayAction(iState_)

        iState_.playTimes = iState_.playTimes + 1
        --print("simple play times = " .. tostring(iState_.playTimes))
        self:AddToQueue(iState_)

        --print( "正式切入: " .. tostring(iState_.name) )
        self.frameCount = 0 -- 重置计数器
        self._workType = WorkType.Interactive

        self:PlayVideoSubtitle(iState_.videoSubtitle) -- 播放字幕
        
        return true

    elseif iState_.stateType == StateType.Timeline then
        printError(" 不再支持 Timeline ")


    elseif iState_.stateType == StateType.SuperTimeline then

        local cameraMode = self.idolLive3D_CameraEnv:GetCameraMode()
        if cameraMode == IdolLive3D_States.CameraMode.Freeze then       -- !!! Freeze 模式暂不支持触发 superTimeline
            return false
        end 

        self:_Into_SuperTimelineState(iState_)        
        return true
    else
        printError(" 目标 state 的 stateType 类型异常: " .. tostring(iState_.name) )
        return false
    end     
end




-- 进入 入场第一个 superTimeline 交互状态:
---@return boolean @ 是否成功进入目标 state
function IdolLive3D_InteractiveManagerV2:IntoInitSuperTimelineIState( iState_ )
    if type(iState_) ~= "table" then 
        printError("koko- 参数异常")
        return false
    end 
    
    if iState_.stateType == StateType.SuperTimeline then
        self:_Into_SuperTimelineState(iState_)
    else 
        printError("iState_ 异常, stateType = " .. tostring(iState_.stateType))
        return false
    end
    return true
end



function IdolLive3D_InteractiveManagerV2:_Into_SuperTimelineState( iState_ )
    --printError("_Into_SuperTimelineState")

    local superTimelineStateEnv = self.superTimelineStateEnvMaps[iState_.name]
    if isNull(superTimelineStateEnv) then 
        printError("没找到 superTimelineStateEnv")
        return false
    end 

    self:BroadcastPlayAction(iState_)
    iState_.playTimes = iState_.playTimes + 1
    self:AddToQueue(iState_)

    superTimelineStateEnv:Play()
    -- !!! 此处是否有必要改写 _workType ???
end



