-- iState 的播放次数是否满了
function IdolLive3D_InteractiveManagerV2:IsPlayTimesOverflow( iState_ )
    if type(iState_.maxPlayTimes) ~= "number" then 
        printError("检查代码")
        iState_.maxPlayTimes = -1
    end
    -- 小于 1 的值都表示 无限次的意思
    if iState_.maxPlayTimes < 1 or iState_.playTimes < iState_.maxPlayTimes then 
        return false
    end 
    return true
end


