    ---
    local frontStageJson = self.roleAnimatorMgr.frontStageJson
    for _,iState in pairs(frontStageJson.InteractiveStates) do 
        if      iState.interactiveType == InteractiveType.Spacial 
            and iState.isCurrentActive == true
            and iState.stateType ~= StateType.Idle
            and IdolLive3D_Utils:IsCameraSpatialParamsInRange(iState.cameraSpatialRange, cameraSpatialParams_, iState.compareMode )
