-- ================================================ 音效 ========================================================== 


function IdolLive3D_InteractiveManagerV2:UpdateSoundsInsideInteractive()

    for cueName,sd in pairs(self.soundDatas) do 

        if sd.pattern == IdolLive3D_States.SoundPattern.Default then
            -- 一次性播放:
            local timeOffset = Time.time - self.registSoundsStartTime
            if isTable(sd) and sd.waitTime <= timeOffset then 
                IdolLive3D_Sounds:PlaySound( sd.sheetName, sd.cueName, sd.soundType, sd.gameObject, sd.isNeedSaveVoice )
                self.soundDatas[cueName] = nil
            end

        elseif sd.pattern == IdolLive3D_States.SoundPattern.TimelineLoop then 
            -- 每次 timeline clip 循环一次, 本 cue 就要被播放一次:
            local playDatas = sd.GetPlayDatasCB() 

            if isTable(sd) and sd.waitTime <= playDatas.playTime and sd.callTimes <= playDatas.loopInteger then 
                IdolLive3D_Sounds:PlaySound( sd.sheetName, sd.cueName, sd.soundType, sd.gameObject, sd.isNeedSaveVoice )
                sd.callTimes = sd.callTimes + 1
            end

        else 
            printError("sd.pattern 值异常:"..tostring(sd.pattern))
        end 

    end

    if self._workType == WorkType.FreeSound and table.count(self.soundDatas) == 0 then 
        print(" _workType: Sound -> Node ")
        self._workType = WorkType.None
        ---
        self.currentPlayingIdleState = self.roleAnimatorMgr:FindCurrentPlayingIdleState()
        if isNotNull(self.currentPlayingIdleState) then 
            self:AddToQueue( self.currentPlayingIdleState )
        end
    end
end


---@param GetPlayDatasCB_ function @ 得到 IdolLive3D_TimeLineStateV2 中的 play table;  可为 nil
function IdolLive3D_InteractiveManagerV2:RegistSounds( iState_, isNeedSaveVoice_, GetPlayDatasCB_ ) 

    self.registSoundsStartTime = Time.time

    self.soundDatas = {} -- clear all
    if isNotNull(iState_.sounds) then 

        for _,sd in pairs(iState_.sounds) do 
            if type(sd.sheetName)=="string" and type(sd.cueName)=="string" and type(sd.soundType)=="number" and #sd.cueName > 0 then 

                -- 找出 json 中可能绑定的 gameNode 
                local idolLive3D_FreeNodesMgr = self.idolLive3D_Main.idolLive3D_FreeNodesMgr
                local soundNode = nil
                if string.isEmpty(sd.gameNodeKey) == false and idolLive3D_FreeNodesMgr then 
                    soundNode = idolLive3D_FreeNodesMgr:FindNode(sd.gameNodeKey, type_soundObject) -- maybe nil
                end
                
                -- CriAtomSource go:
                local sourceGO = (sd.soundType == IdolLive3D_States.CueType.SFX) and IdolLive3D_Sounds.sfxSourceGO or self.roleGO
                local bindObj = (soundNode==nil) and sourceGO or soundNode.transform.gameObject

                
                --printError("音 cue:"..tostring(sd.cueName)..", obj:"..tostring(bindObj.name))
                -- 

                if sd.soundPattern == IdolLive3D_States.SoundPattern.TimelineLoop then 
                    if isNull(GetPlayDatasCB_) then 
                        printError(" sound cue 配置异常, 需检查 json 或代码")
                        sd.soundPattern = IdolLive3D_States.SoundPattern.Default -- 让错误变哑变安全
                    end
                end 
                
                -- 防御:
                if isNull(sd.soundPattern) then 
                    printError("异常, soundPattern 为 nil; 现手动改为 Default;  cue = " .. tostring(sd.cueName))
                    sd.soundPattern = IdolLive3D_States.SoundPattern.Default
                end 

                --printError( "push cue: " .. tostring(sd.cueName) )
                self.soundDatas[sd.cueName] = {
                    waitTime = Mathf.Max(0.0, sd.waitTime ),
                    sheetName = sd.sheetName,
                    cueName = sd.cueName,
                    soundType = sd.soundType,
                    pattern = sd.soundPattern,
                    isNeedSaveVoice = (isNeedSaveVoice_ == true),
                    gameObject = bindObj,
                    callTimes = 0, -- 每次开始播放本 cue, 本值累加1
                    GetPlayDatasCB = GetPlayDatasCB_,
                }

                table.insert(self.needStoppedSoundDatas, {
                    sheetName = sd.sheetName,
                    cueName = sd.cueName,
                    soundType = sd.soundType,
                })


            end 
        end 
    end 
end



function IdolLive3D_InteractiveManagerV2:IntoNewState() 

    for i=1, #self.needStoppedSoundDatas do 
        local soundData = self.needStoppedSoundDatas[i]
        IdolLive3D_Sounds.Stop(soundData.sheetName, soundData.cueName, soundData.soundType)
    end
    self.needStoppedSoundDatas = {}

end 


-- ================================================ queue ========================================================== 

-- !!! 感觉这部分 可以被独立出去 ...

-- !! 务必保证本函数能忠实地记录 istate 的切换;
---@param iState table 
---@param superTimelineClipInfo_ table | nil
function IdolLive3D_InteractiveManagerV2:AddToQueue( iState_, superTimelineClipInfo_ )
    if IdolLive3D_States.IsValidIStateType(iState_.stateType) == false then 
        printError("stateType 异常: " .. tostring(iState_.stateType))
    end 

    if isNull(superTimelineClipInfo_) then
        self:_AddToQueueLast( { iStateName = iState_.name} )
        -- ===== new iState =====
        print( "add queue: - iState: " .. tostring(iState_.name) .. ", stateType: " .. IdolLive3D_States.GetStateTypeString(iState_.stateType) .. "; frame: " .. tostring(self.longFrameCount) )
        Events.Broadcast(IdolLive3D_States.EventNewInteractiveState, iState_)

        --- 特殊阶段要锁玩家操作:
        -- (timeline 阶段的锁被放到别处了) -- !! 要检查
        IdolLive3D_States.isForbidPlayerSwipeAndPinch = (iState_.stateType == IdolLive3D_States.InteractiveStateType.StageJump)

    else 
        -- ===== new superTimeline Clip =====
        local clipId = superTimelineClipInfo_.clipId -- string
        local clipJson = superTimelineClipInfo_.clipJson
        print( "add queue: - clip: " .. tostring(iState_.name) .. ", stateType: " .. IdolLive3D_States.GetStateTypeString(iState_.stateType) .. ", clip: " .. tostring(clipId) )
        
        self:_AddToQueueLast( { iStateName = iState_.name, clipInfo = superTimelineClipInfo_ } )
    end
end


function IdolLive3D_InteractiveManagerV2:_AddToQueueLast(ent_) 
    while self.interactiveStateQueue:Count() >= self.interactiveStateQueueMaxNum do 
        self.interactiveStateQueue:RemoveFirst()
    end 
    self.interactiveStateQueue:AddLast( ent_ )
    --print( "add queue: - name: " .. tostring(ent_.iStateName)  )
end


---@return table @ 记得使用 ret.iState
function IdolLive3D_InteractiveManagerV2:PeekLastInteractiveStateFromQueue()

    if self.interactiveStateQueue:Count() == 0 then 
        printError("queue 为 空, 代码逻辑异常")
        return nil
    end 
    ---
    local ent = self.interactiveStateQueue:PeekLast() -- table 
    local name = ent.iStateName
    ---
    local iStateA = self.roleAnimatorMgr.frontStageJson.name_to_InteractiveStates[name]
    if isNotNull( iStateA ) then 
        ent.iState = iStateA
        return ent
    end 
    ---
    local iStateB = self.baseJson.superTimeline_name_to_InteractiveStates[name]
    if isNotNull( iStateB ) then 
        ent.iState = iStateB
        return ent
    end 
    --- 
    local iStateC = self.baseJson.stageJump_name_to_InteractiveStates[name]
    if isNotNull( iStateC ) then 
        ent.iState = iStateC
        return ent
    end 
    ---
    printError( "异常, 反解表 name_to_InteractiveStates 中没找到元素: " .. tostring(name) )
    return nil
end 


-- 如果某代码希望在 Idle 状态执行, 可使用本函数:
---@return boolean | nil  @ 只有当 ret true 时, 才算是在正式的 idle 阶段, 返回 nil 可能有多种因素
function IdolLive3D_InteractiveManagerV2:IsInIdleState()
    if self.isInit ~= true then 
        printError("调用时机异常: InteractiveManagerV2 尚未初始化")
        return nil
    end 

    if self.interactiveStateQueue:Count() == 0 then 
        return nil
    end

    local lastEnt = self:PeekLastInteractiveStateFromQueue()
    if isNull(lastEnt) then 
        return nil
    end

    return lastEnt.iState.stateType == IdolLive3D_States.InteractiveStateType.Idle
end


-- ================================================


function IdolLive3D_InteractiveManagerV2:CurrentInteractiveStateIsOpenLookAt()
    local queEnt = self:PeekLastInteractiveStateFromQueue()
    local iState = queEnt.iState
    if isNull(iState) then 
        return true
    end 
    ---
    if iState.stateType == StateType.Simple and iState.isCloseLookAt == true then 
        return false
    end
    -- superTimeline 中, 只处理 clip ent:
    if iState.stateType == StateType.SuperTimeline and isNotNull(queEnt.clipInfo) then 
        if isNull(queEnt.clipInfo.clipJson) or isNull(queEnt.clipInfo.clipJson.isCloseLookAt) then 
            printError("queue 数据缺失, iState: " .. tostring(queEnt.iStateName))
            return true
        end 
        if queEnt.clipInfo.clipJson.isCloseLookAt == true then 
            return false
        end 

    end     
    return true
end


-- 在一个 simple iState 播放完毕后, 检查它是否包含 fx, 如果有, 将 fx 关闭
function IdolLive3D_InteractiveManagerV2:_CheckAndHideSimpleFX() 

    local queEnt = self:PeekLastInteractiveStateFromQueue() 
    local iState = queEnt.iState
    if iState.stateType == StateType.Simple and isNotNull(iState.fxTF) then 
        KTool.SetActive( iState.fxTF.gameObject, false )
    end 
end


-- 播放字幕
function IdolLive3D_InteractiveManagerV2:PlayVideoSubtitle( videoSubtitle ) 
    --printError("播放字幕 - " .. tostring(videoSubtitle.id))
    if string.isEmpty(videoSubtitle.id) == false and type(videoSubtitle.waitTime) == "number" then 
        --printError( "发生 字幕请求: " .. tostring(videoSubtitle.id)  )
        Events.Broadcast(IdolLive3D_States.EventPlayVideoSubtitle, videoSubtitle.id, videoSubtitle.waitTime)
    end 
end 






return IdolLive3D_InteractiveManagerV2
